def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)
        value = value.strip().lower()

        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in ("gmail.com", "googlemail.com"):
                local = local.split("+", 1)[0].replace(".", "")
                value = local + "@gmail.com"
        return value

    def valid_email(value):
        if value.count("@") != 1:
            return False
        local, domain = value.split("@")
        return bool(local) and "." in domain and not domain.startswith(".") and not domain.endswith(".")

    def normalize_phone(value):
        match = re.search(r"ext|x|#", value, flags=re.IGNORECASE)
        if match:
            value = value[:match.start()]
        digits = "".join(ch for ch in value if ch.isdigit())
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        return digits

    def valid_phone(value):
        return len(value) == 10 and value[0] not in "01"

    def normalize_zip(value):
        value = value.strip()
        if "-" in value:
            value = value.split("-", 1)[0]
        if len(value) == 4 and value.isdigit():
            value = "0" + value
        return value if len(value) == 5 and value.isdigit() else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        if "T" in value:
            return datetime.strptime(value, "%Y-%m-%dT%H:%M:%S")
        if "/" in value:
            return datetime.strptime(value, "%m/%d/%Y")
        return datetime.strptime(value, "%Y-%m-%d")

    prepared = []
    for index, row in enumerate(rows):
        email = normalize_email(row["email"])
        email = email if valid_email(email) else ""

        phone = normalize_phone(row["phone"])
        phone = phone if valid_phone(phone) else ""

        if not email and not phone:
            continue

        updated = parse_updated(row["updated"])
        prepared.append({
            "index": index,
            "email": email,
            "phone": phone,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "zip": normalize_zip(row["zip"]),
            "source": row["source"].strip().lower(),
            "updated_dt": updated,
            "opted_out": row["opted_out"].strip().lower() in {"y", "yes", "true", "1"},
            "tags": row["tags"],
        })

    parent = list(range(len(prepared)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    email_owner = {}
    phone_name_owner = {}

    for i, row in enumerate(prepared):
        if row["email"]:
            if row["email"] in email_owner:
                union(i, email_owner[row["email"]])
            else:
                email_owner[row["email"]] = i

        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].lower())
            if key in phone_name_owner:
                union(i, phone_name_owner[key])
            else:
                phone_name_owner[key] = i

    groups = {}
    for i, row in enumerate(prepared):
        groups.setdefault(find(i), []).append(row)

    def pick(group, field, require_valid=False):
        candidates = [
            row for row in group
            if row[field] and (not require_valid or row[field])
        ]
        if not candidates:
            return ""
        chosen = min(
            candidates,
            key=lambda row: (
                row["source"] != "manual",
                -row["updated_dt"].timestamp(),
                row["index"],
            ),
        )
        return chosen[field]

    output = []
    for group in sorted(groups.values(), key=lambda g: min(r["index"] for r in g)):
        tags = set()
        for row in group:
            tags.update(
                tag.strip().lower()
                for tag in re.split(r"[;,]", row["tags"])
                if tag.strip()
            )

        latest = max(row["updated_dt"] for row in group)
        output.append({
            "first_name": pick(group, "first_name"),
            "last_name": pick(group, "last_name"),
            "zip": pick(group, "zip"),
            "email": pick(group, "email", require_valid=True),
            "phone": pick(group, "phone", require_valid=True),
            "source": pick(group, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(row["opted_out"] for row in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return output
